import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a minimum-cost shared directed multicast tree.

    For up to twelve destinations, use subset dynamic programming for the
    directed Steiner tree rooted at ``src``.  The objective is the cost of the
    union of links, so a link carrying data to several downstream clouds is
    charged only once.  Larger instances use several marginal-cost greedy
    starts to retain bounded runtime.
    """
    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))

    h = nx.DiGraph()
    for u, v, data in G.edges(data=True):
        cost = data.get("cost")
        if u != v and v != src and cost is not None:
            try:
                cost = float(cost)
                if cost >= 0:
                    h.add_edge(u, v, cost=cost)
            except (TypeError, ValueError):
                pass

    if not terminals:
        for dst in dsts:
            for partition in range(num_partitions):
                bc_topology.set_dst_partition_paths(dst, partition, [])
        return bc_topology

    nodes = list(h.nodes)
    if src not in h:
        return bc_topology

    def install(edge_set):
        tree = nx.DiGraph()
        tree.add_edges_from(edge_set)
        for dst in dsts:
            try:
                node_path = [] if dst == src else nx.shortest_path(tree, src, dst)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                continue
            edge_path = [[u, v, G[u][v]]
                         for u, v in zip(node_path, node_path[1:])]
            for partition in range(num_partitions):
                bc_topology.set_dst_partition_paths(dst, partition, edge_path)

    # Exact Dreyfus-Wagner style DP.  dp[mask][v] is the cheapest arborescence
    # rooted at v that reaches every terminal represented by mask.
    if len(terminals) <= 12 and all(dst in h for dst in terminals):
        reverse = {v: [] for v in nodes}
        for u, v, data in h.edges(data=True):
            reverse[v].append((u, data["cost"]))

        count = 1 << len(terminals)
        dp = [[float("inf")] * len(nodes) for _ in range(count)]
        choice = [[None] * len(nodes) for _ in range(count)]
        index = {v: i for i, v in enumerate(nodes)}

        for bit, dst in enumerate(terminals):
            dp[1 << bit][index[dst]] = 0.0
            choice[1 << bit][index[dst]] = ("terminal",)

        import heapq
        for mask in range(1, count):
            if mask & (mask - 1):
                for part in range((mask - 1) & mask, 0,
                                  -1 & ((mask - 1) & mask)):
                    other = mask ^ part
                    if other == 0 or part > other:
                        continue
                    for i in range(len(nodes)):
                        value = dp[part][i] + dp[other][i]
                        if value < dp[mask][i]:
                            dp[mask][i] = value
                            choice[mask][i] = ("split", part, other)

            heap = [(dp[mask][i], i) for i in range(len(nodes))
                    if dp[mask][i] < float("inf")]
            heapq.heapify(heap)
            while heap:
                value, vi = heapq.heappop(heap)
                if value != dp[mask][vi]:
                    continue
                v = nodes[vi]
                for u, edge_cost in reverse[v]:
                    ui = index[u]
                    candidate = value + edge_cost
                    if candidate < dp[mask][ui]:
                        dp[mask][ui] = candidate
                        choice[mask][ui] = ("edge", v)
                        heapq.heappush(heap, (candidate, ui))

        full = count - 1
        if dp[full][index[src]] < float("inf"):
            selected_edges = set()

            def recover(mask, node):
                action = choice[mask][index[node]]
                if action is None or action[0] == "terminal":
                    return
                if action[0] == "split":
                    recover(action[1], node)
                    recover(action[2], node)
                else:
                    nxt = action[1]
                    selected_edges.add((node, nxt))
                    recover(mask, nxt)

            recover(full, src)
            install(selected_edges)
            return bc_topology

    # Greedy fallback tries every first branch, reducing sensitivity to the
    # order in which destination regions happen to be listed.
    def greedy(first=None):
        selected, remaining = set(), set(terminals)
        if first is not None:
            remaining.remove(first)
            try:
                path = nx.shortest_path(h, src, first, weight="cost")
                selected.update(zip(path, path[1:]))
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                return set()

        while remaining:
            def weight(u, v, data):
                return 0.0 if (u, v) in selected else data["cost"]

            distances, paths = nx.single_source_dijkstra(h, src, weight=weight)
            reachable = [dst for dst in remaining if dst in distances]
            if not reachable:
                break
            dst = min(reachable, key=distances.get)
            selected.update(zip(paths[dst], paths[dst][1:]))
            remaining.remove(dst)
        return selected

    candidates = [greedy()] + [greedy(dst) for dst in terminals]
    best = min(candidates, key=lambda edges: sum(h[u][v]["cost"]
                                                  for u, v in edges))
    install(best)
    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


